    /// Print each phase + status + resume point for a run.
    Status { name: String },

    /// Print the directory a run's phases work in — the worktree path for a
    /// worktree run — so `$(drovr path <run>)` substitutes directly.
    Path { name: String },

    /// Attach to the current phase's pane.
    Attach { name: String },

    /// Block until one of a run's agents is stuck on a prompt only a human can
    name: &str,
    task: Option<String>,
    dir: Option<PathBuf>,
    worktree_flag: bool,
    no_worktree_flag: bool,
    herdr: &H,
) -> io::Result<RunState> {
    let cfg = config::load_config()
        .map_err(|e| io::Error::other(format!("drovr: failed to load config: {e}")))?;
    let agent = config::invoking_agent(&cfg);
    if !cfg.agents.contains_key(&agent) {
        return Err(io::Error::other(format!(
            "drovr: detected unknown agent '{agent}': add it to the config agent map"
        )));
    }
    if !herdr.integration_present(&agent) {
        return Err(io::Error::other(format!(
            "prerequisite missing: run 'herdr integration install {agent}'"
        )));
    }

    let project_dir = match dir {
        Some(d) => {
            if !d.exists() {
                return Err(io::Error::new(
                    io::ErrorKind::NotFound,
                    format!("drovr: --dir path does not exist: {}", d.display()),
                ));
            }
            d.to_string_lossy().into_owned()
        }
        None => std::env::current_dir()
            .map_err(|e| {
                io::Error::new(
                    e.kind(),
                    format!("drovr: cannot determine current directory: {e}"),
                )
            })?
            .to_string_lossy()
            .into_owned(),
    };

    // Resolve worktree isolation: --no-worktree wins, then --worktree, else the
    // config default. When on, redirect project_dir into a fresh worktree so the
    // whole run (panes, code-review base, phase edits) lands there, never in the
    // invoking checkout.
    let use_worktree = if no_worktree_flag {
        false
    } else {
        worktree_flag || cfg.worktree
    };
    let (project_dir, worktree_path, worktree_branch) = if use_worktree {
        match worktree::create(std::path::Path::new(&project_dir), name) {
            Ok((abs, branch)) => {
                let p = abs.to_string_lossy().into_owned();
                println!("drovr: worktree {p} on branch {branch}");
                // D1: reporting the path is not enough. drovr is a subprocess and
                // cannot move its caller, and a `cd` inside a tool call does not
                // survive to the next one — so the driver stays in the invoking
                // checkout unless it is told, here, to move itself. Built from the
                // same fragment as the D3 wrong-tree warning so the two cannot drift.
                println!(
                    "drovr: ENTER IT — {} — drovr cannot move you; `cd` does not persist.",
                    worktree::enter_instruction(&p)
                );
                (p.clone(), Some(p), Some(branch))
